/// The SVG bytes of a Tabler icon, or `None` for an unknown name.
pub fn icon(name: &str) -> Option<&'static [u8]> {
    ICONS
        .binary_search_by_key(&name, |def| def.name)
        .ok()
        .and_then(|index| ICONS.get(index))
        .map(|def| def.bytes)
}

/// One icon-map row, or `None` for an unknown key.
pub fn entry(key: &str) -> Option<&'static IconEntryDef> {
    ENTRIES
        .binary_search_by_key(&key, |def| def.key)
        .ok()
        .and_then(|index| ENTRIES.get(index))
}
